class Box {
  constructor(value) {
    this.value = value;
  }

  then(onFulfilled) {
    console.log("then called");
    onFulfilled(this.value);
  }
}

async function main() {
  console.log("before");
  const value = await new Box(5);
  console.log("got " + value);
}

main();
Promise.resolve().then(() => console.log("microtask"));
console.log("sync end");
